std::vector<double> result;
result.reserve(2 * dim - 1);

if (dim == 0) {
    return result;
}

// H_0(x) = 1
result.push_back(1.0);

if (dim > 1) {
    // H_1(x) = 2x
    result.push_back(2.0 * x);

    for (size_t l = 2; l < 2 * dim - 1; ++l) {
        // Use the recurrence relation via hermite_next
        // H_l(x) = hermite_next(l, x, H_{l-1}, H_{l-2})
        result.push_back(hermite_next(l, x, result[l - 1], result[l - 2]));
    }
}

return result;
// END_CODE

